create table if not exists job_source_observations (id uuid primary key,job_id uuid not null references jobs(id) on delete cascade,source_type text not null,provider text not null,source_url text,external_job_id text not null default '',discovered_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),content_hash text,extraction_hash text,extraction_confidence numeric(5,4),source_status text not null default 'SEEN',unique(provider,source_url,external_job_id));
create index if not exists job_source_observations_job_idx on job_source_observations(job_id,last_seen_at desc);
create table if not exists discovery_extractions (id uuid primary key,correlation_id text not null,provider text not null,source_url text,started_at timestamptz not null,completed_at timestamptz,result jsonb not null default '{}',confidence numeric(5,4),error text,retry_count int not null default 0,comparison_result jsonb,created_at timestamptz not null default now());
create index if not exists discovery_extractions_correlation_idx on discovery_extractions(correlation_id,created_at desc);
alter table job_sources add column if not exists provider_config jsonb not null default '{}';
